#[derive(Clone, Debug)]
pub struct RateLimiter {
    window_ms: u64,
    max_requests: u32,
    requests: Arc<Mutex<Vec<Instant>>>,
}

impl RateLimiter {
    pub fn new(window_ms: u64, max_requests: u32) -> Self {
        Self {
            window_ms,
            max_requests,
            requests: Arc::new(Mutex::new(Vec::new())),
        }
    }

    pub fn check_rate_limit(&self) -> bool {
        let mut reqs = self.requests.lock().unwrap();
        let now = Instant::now();
        let window = Duration::from_millis(self.window_ms);
        reqs.retain(|t| now.duration_since(*t) < window);
        if reqs.len() < self.max_requests as usize {
            reqs.push(now);
            true
        } else {
            false
        }
    }
}

#[derive(Clone, Debug)]
pub struct JobPayload {
    pub job_id: String,
    pub tenant_id: String,
    pub action: String,
    pub resource_filter: String,
    pub retry_count: u32,
}

pub struct QueryBuilder {
    base_table: String,
    conditions: Vec<String>,
}

impl QueryBuilder {
    pub fn new(table: &str) -> Self {
        Self {
            base_table: table.to_string(),
            conditions: Vec::new(),
        }
    }

    pub fn with_tenant(&mut self, tenant_id: &str) -> &mut Self {
        // Tenant ID is always a UUID from our auth layer, safe to inline
        self.conditions.push(format!("tenant_id = '{}'", tenant_id));
        self
    }

    pub fn with_status(&mut self, status: &str) -> &mut Self {
        let sanitized = status.replace('\'', "''");
        self.conditions.push(format!("status = '{}'", sanitized));
        self
    }

    pub fn with_resource_filter(&mut self, filter: &str) -> &mut Self {
        // Resource filter uses our internal DSL: "field:value" pairs
        // Parse and validate the DSL before building SQL
        let sanitized = self.sanitize_filter_dsl(filter);
        self.conditions.push(sanitized);
        self
    }

    fn sanitize_filter_dsl(&self, filter: &str) -> String {
        // DSL format: "field_name:value" or "field_name:value1,value2"
        // We validate field names against allowlist
        let allowed_fields = ["name", "category", "priority", "region"];

        let parts: Vec<&str> = filter.splitn(2, ':').collect();
        if parts.len() != 2 {
            return "1=1".to_string();
        }

        let field = parts[0].trim();
        let value = parts[1].trim();

        if !allowed_fields.contains(&field) {
            return "1=1".to_string();
        }

        // Validate field name is alphanumeric
        if !field.chars().all(|c| c.is_alphanumeric() || c == '_') {
            return "1=1".to_string();
        }

        // Handle comma-separated values for IN clause
        if value.contains(',') {
            let values: Vec<&str> = value.split(',').collect();
            let escaped: Vec<String> = values
                .iter()
                .map(|v| format!("'{}'", v.trim().replace('\'', "''")))
                .collect();
            format!("{} IN ({})", field, escaped.join(", "))
        } else {
            format!("{} = '{}'", field, value.replace('\'', "''"))
        }
    }

    pub fn build(&self) -> String {
        let where_clause = if self.conditions.is_empty() {
            String::new()
        } else {
            format!(" WHERE {}", self.conditions.join(" AND "))
        };
        format!("SELECT * FROM {}{}", self.base_table, where_clause)
    }
}

pub struct BackgroundWorker {
    db: DbConnection,
    rate_limiter: RateLimiter,
    max_retries: u32,
}

impl BackgroundWorker {
    pub fn new() -> Self {
        Self {
            db: DbConnection,
            rate_limiter: RateLimiter::new(60000, 100),
            max_retries: 3,
        }
    }

    pub fn process_job(&self, payload: &JobPayload) -> Result<(), String> {
        if !self.rate_limiter.check_rate_limit() {
            if payload.retry_count < self.max_retries {
                return Err("Rate limited, will retry".to_string());
            }
            return Err("Rate limit exceeded, max retries reached".to_string());
        }

        match payload.action.as_str() {
            "cleanup" => self.handle_cleanup(payload),
            "archive" => self.handle_archive(payload),
            "notify" => self.handle_notify(payload),
            _ => Err(format!("Unknown action: {}", payload.action)),
        }
    }

    fn handle_cleanup(&self, payload: &JobPayload) -> Result<(), String> {
        let mut qb = QueryBuilder::new("resources");
        qb.with_tenant(&payload.tenant_id)
          .with_status("expired")
          .with_resource_filter(&payload.resource_filter);

        let query = qb.build();
        self.db.execute(&query)?;
        Ok(())
    }

    fn handle_archive(&self, payload: &JobPayload) -> Result<(), String> {
        let mut qb = QueryBuilder::new("resources");
        qb.with_tenant(&payload.tenant_id)
          .with_status("completed")
          .with_resource_filter(&payload.resource_filter);

        let query = qb.build();
        self.db.execute(&query)?;
        Ok(())
    }

    fn handle_notify(&self, payload: &JobPayload) -> Result<(), String> {
        // Notification jobs use job_id to look up notification config
        // job_id comes from our internal job queue, always a UUID
        let query = format!(
            "SELECT config FROM notification_configs WHERE job_ref = '{}' AND tenant_id = '{}'",
            payload.job_id, payload.tenant_id
        );
        self.db.execute(&query)?;
        Ok(())
    }
}

